cd /workspace && python3 - <<'PY'
import subprocess,sys,json
P='/app/submission/scheduler.py'
def run(payload):
    if not isinstance(payload,(bytes,)):
        payload=payload.encode()
    r=subprocess.run([sys.executable,'-I','-B',P],input=payload,stdout=subprocess.PIPE)
    return r.returncode, r.stdout.decode().strip()
tests={
 "nested_dup":'{"mode":"burst","banks":1,"lanes":1,"limit":10,"borders":[0,10],"start_bank":0,"packets":[{"id":"a","id":"b","lane":0,"rank":1}]}',
 "bool_border":'{"mode":"burst","banks":1,"lanes":1,"limit":10,"borders":[0,10],"start_bank":0,"packets":[{"id":"a","lane":0,"rank":true}]}',
 "string_lane":'{"mode":"burst","banks":1,"lanes":1,"limit":10,"borders":[0,10],"start_bank":0,"packets":[{"id":"a","lane":"0","rank":1}]}',
 "inf":'{"mode":"burst","banks":1,"lanes":1,"limit":10,"borders":[0,10],"start_bank":0,"packets":[] ,"x":Infinity}',
 "valid_one":json.dumps({"mode":"burst","banks":1,"lanes":1,"limit":3,"borders":[0,3],"start_bank":0,"packets":[{"id":"A_9-z","lane":0,"rank":2}]}),
 "id_toolong":"{\"mode\":\"burst\",\"banks\":1,\"lanes\":1,\"limit\":10,\"borders\":[0,10],\"start_bank\":0,\"packets\":[{\"id\":\"%s\",\"lane\":0,\"rank\":1}]}"%("a"*33),
}
for name,p in tests.items():
    rc,out=run(p)
    print(name,rc,out[:70])
PY

